// world/zone.js — Данные стартовой зоны NEXUS (текстовый/1D MUD-срез).
//
// Это «лист»-модуль: чистые данные мира + минимальный геттер.
// Другие модули (knowledge, echo, textui, main) импортируют ОТСЮДА,
// сам он ничего из систем не тянет — так зона остаётся источником истины
// о топологии комнат, рунах (столп ЗНАНИЕ) и местах для эха (столп ЭХО).
//
// Модель руны: каждая руна дешифруется ТОЛЬКО при известном факте (factId).
// Сам факт хранится в systems/knowledge.js; здесь руна лишь ссылается на него
// через поле `fact` и несёт зашифрованный/расшифрованный текст.
//
// Привязка: NX-VIS-004 (мета-слой «Койне»), столпы ЭХО + ЗНАНИЕ.

/**
 * Комнаты зоны «Преддверие Койне».
 * Форма комнаты (по контракту):
 *   { id, name, desc, exits:{dir:roomId}, runes:[runeId], items:[] }
 * Направления выходов — на русском (север/юг/восток/запад/вниз/вверх);
 * парсер в textui сам маппит англ. синонимы на эти ключи.
 *
 * 4 руны распределены по комнатам; каждая завязана на свой факт:
 *   rune-portal  ← fact:arch-key   (узнать в зале архивов)
 *   rune-altar   ← fact:echo-rite  (узнать у алтаря отголосков)
 *   rune-vault   ← fact:vault-word (узнать в галерее имён)
 */
export const zones = {
  start: {
    id: 'start',
    name: 'Порог Странника',
    desc:
      'Холодный камень под ногами, в воздухе — гул, будто кто-то шепчет ' +
      'сквозь толщу веков. Это Преддверие Койне: место, где записи мира ' +
      'оседают слоями. На северной стене тлеет руна, но её знаки немы.',
    exits: { север: 'archive', восток: 'altar' },
    runes: ['rune-portal'],
    items: ['истёртая монета'],
  },

  archive: {
    id: 'archive',
    name: 'Зал Архивов',
    desc:
      'Полки уходят во мрак, набитые табличками с засечками. Среди пыли ' +
      'различима пометка писца: «Ключ свода — слово, открывающее портал». ' +
      'Если вчитаться, можно изучить этот факт (arch-key).',
    exits: { юг: 'start', восток: 'gallery' },
    runes: [],
    items: ['пустая табличка'],
  },

  altar: {
    id: 'altar',
    name: 'Алтарь Отголосков',
    desc:
      'Чаша из тёмной бронзы. Капля упавшей воды звучит дважды — эхо живёт ' +
      'здесь дольше, чем где-либо. На ободе гравировка: «Обряд отголоска — ' +
      'оставить слово месту» (echo-rite). У дальней стены ждёт руна.',
    exits: { запад: 'start', север: 'gallery' },
    runes: ['rune-altar'],
    items: [],
  },

  gallery: {
    id: 'gallery',
    name: 'Галерея Имён',
    desc:
      'Длинный проход, где на плитах выбиты имена тех, кто прошёл прежде. ' +
      'Одно слово светится ярче прочих — «слово свода» (vault-word). ' +
      'Отсюда лестница ведёт вниз, к запертой руне.',
    exits: { запад: 'archive', юг: 'altar', вниз: 'vault' },
    runes: [],
    items: ['осколок зеркала'],
  },

  vault: {
    id: 'vault',
    name: 'Свод Койне',
    desc:
      'Круглая палата под землёй. В центре — руна, врезанная в пол, ' +
      'пульсирующая в такт дальнему гулу. Здесь субстрат записей обнажён: ' +
      'кажется, любое оставленное слово останется навсегда.',
    exits: { вверх: 'gallery' },
    runes: ['rune-vault'],
    items: [],
  },
};

/**
 * Руны зоны. Каждая дешифруется только при известном факте `fact`.
 *   id     — идентификатор руны (то, что в room.runes)
 *   name   — как руна называется при осмотре/чтении
 *   fact   — factId, без которого `decode` вернёт {ok:false}
 *   locked — текст для НЕизвестного факта (что видно до дешифровки)
 *   text   — расшифрованный текст (выдаётся, когда факт известен)
 * knowledge.decode(runeId) читает именно эту таблицу.
 */
export const runes = {
  'rune-portal': {
    id: 'rune-portal',
    name: 'Руна Портала',
    fact: 'arch-key',
    locked:
      'Знаки сплетаются и расходятся — смысл ускользает. Чего-то ты ещё не знаешь.',
    text:
      'РУНА ПОРТАЛА проясняется: «Кто держит ключ свода, тому откроется путь ' +
      'вглубь Койне. Спустись, когда узнаешь слово».',
  },
  'rune-altar': {
    id: 'rune-altar',
    name: 'Руна Отголоска',
    fact: 'echo-rite',
    locked:
      'Гравировка дрожит, как отражение в воде, и не складывается в слова.',
    text:
      'РУНА ОТГОЛОСКА звучит в голове: «Оставь слово месту — и оно будет ' +
      'звучать для тех, кто придёт после. Так творится эхо».',
  },
  'rune-vault': {
    id: 'rune-vault',
    name: 'Руна Свода',
    fact: 'vault-word',
    locked:
      'Руна горит, но её центральный глиф запечатан незнакомым словом.',
    text:
      'РУНА СВОДА раскрывается: «Имя, что светилось в галерее, и есть печать. ' +
      'Субстрат принял тебя — отныне твои записи неотделимы от Койне».',
  },
};

/**
 * Изменяемое состояние мира. По контракту минимально: текущая комната.
 * Системы (echo, textui) читают state.room как «место» записей.
 */
export const state = { room: 'start' };

/**
 * Игрок. id используется как author записей в субстрате.
 */
export const player = { id: 'you', name: 'Странник' };

/**
 * Вернуть комнату по id (или undefined, если такой нет).
 * @param {string} id
 * @returns {object|undefined}
 */
export function getRoom(id) {
  return zones[id];
}
